window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e32cf82a3754aca0"]={"versions": [{"id": "FIG-e32cf82a3754aca0", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Klassifikation der AUTOSAR-Software-Komponenten im Kontext der Software-Component Template und der Runtime Environment (RTE). Das Diagramm veranschaulicht die Vererbungshierarchie von Komponententypen ausgehend von <code>ComponentType</code> sowie das Zusammenspiel zwischen Typen und deren instanziierender Verwendung als Prototypen (<code>ComponentPrototype</code>) innerhalb hierarchischer Kompositionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComponentType</code>: Abstrakte Basisklasse mit Stereotyp <code>«atpType»</code>, spezialisiert die AUTOSAR-Basisklasse <code>ARElement</code>.\n</li><li><code>AtomicSoftwareComponentType</code>: Abstrakte Spezialisierung von <code>ComponentType</code>.\n<ul class=\"fig-list\"><li><code>SensorActuatorSoftwareComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ServiceComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li></ul>\n</li><li><code>CalprmComponentType</code>: Spezialisierung von <code>ComponentType</code> mit Stereotyp <code>«atpType»</code> für Kalibrier- und Parameter-Komponenten.\n</li><li><code>CompositionType</code>: Spezialisierung von <code>ComponentType</code> mit Stereotyp <code>«atpType»</code> zur strukturellen Kapselung.\n</li><li><code>ComponentPrototype</code>: Prototyp-Entität mit Stereotyp <code>«atpPrototype»</code>, spezialisiert <code>Identifiable</code>.\n</li><li>Assoziationen und Kompositionen:\n<ul class=\"fig-list\"><li><code>ComponentPrototype</code> referenziert über die gerichtete Assoziation <code>«isOfType»</code> genau einen <code>ComponentType</code> (Rollenname <code>+type</code>, Multiplizität <code>1</code>, Zielseite <code>*</code>).\n</li><li><code>CompositionType</code> enthält über eine Komposition (schwarze Raute) mindestens einen <code>ComponentPrototype</code> (Rollenname <code>+component</code>, Multiplizität <code>1..*</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Die Instanziierungslogik ist deklarativ: Ein <code>CompositionType</code> aggregiert zur Entwurfszeit <code>ComponentPrototype</code>-Elemente, die jeweils typisiert über <code>«isOfType»</code> auf eine konkrete oder kompositionelle <code>ComponentType</code>-Definition verweisen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die fundamentale Typ-Prototyp-Trennung für AUTOSAR-Softwarekomponenten. Da <code>ComponentType</code> abstrakt ist, können nur abgeleitete konkrete Typen typisiert werden. Eine Komposition (<code>CompositionType</code>) erfordert mindestens einen Prototyp (<code>1..*</code>), was leere Kompositionen ausschließt. Software-Architekten und Werkzeughersteller müssen sicherstellen, dass Prototypen ausschließlich valide Typen referenzieren und die Vererbungshierarchie der atomaren Komponenten eingehalten wird.</p>"}, {"id": "FIG-3332cf3134fcc3ef", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm mit Diagrammrahmen <code>cd Components</code> zur Klassifikation der AUTOSAR-Software-Komponenten im Kontext der Software-Component Template und der Runtime Environment (RTE). Das Diagramm veranschaulicht die Typenhierarchie ausgehend von <code>ComponentType</code> einschließlich der an die RTE angebundenen hardware- und basissoftwarenahen Softwarekomponenten sowie die Kompositionsbeziehung zu <code>ComponentPrototype</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm im Rahmen <code>cd Components</code> definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComponentType</code>: Abstrakte Basisklasse mit Stereotyp <code>«atpType»</code>, spezialisiert <code>ARElement</code>.\n</li><li><code>AtomicSoftwareComponentType</code>: Abstrakte Spezialisierung von <code>ComponentType</code>.\n<ul class=\"fig-list\"><li><code>ApplicationSoftwareComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>SensorActuatorSoftwareComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ServiceComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code> (im Diagramm beschriftet als <code>Serv iceComponentType</code>).\n</li><li><code>EcuAbstractionComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ComplexDeviceDriverComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code> (im Diagramm beschriftet als <code>ComplexDev iceDriverComponentType</code>).\n</li></ul>\n</li><li><code>CalprmComponentType</code>: Spezialisierung von <code>ComponentType</code> mit Stereotyp <code>«atpType»</code>.\n</li><li><code>CompositionType</code>: Spezialisierung von <code>ComponentType</code> mit Stereotyp <code>«atpType»</code>.\n</li><li><code>ComponentPrototype</code>: Entität mit Stereotyp <code>«atpPrototype»</code>, spezialisiert <code>Identifiable</code>.\n</li><li>Assoziationen und Kompositionen:\n<ul class=\"fig-list\"><li><code>ComponentPrototype</code> referenziert über die gerichtete Assoziation <code>«isOfType»</code> genau einen <code>ComponentType</code> (Rolle <code>+type</code>, Multiplizität <code>1</code>, Quellmultiplizität <code>*</code>).\n</li><li><code>CompositionType</code> aggregiert per Komposition mindestens einen <code>ComponentPrototype</code> (Rolle <code>+component</code>, Multiplizität <code>1..*</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Die Instanziierungslogik ist deklarativ: Ein <code>CompositionType</code> aggregiert zur Entwurfszeit <code>ComponentPrototype</code>-Elemente, die jeweils typisiert über <code>«isOfType»</code> auf eine konkrete oder kompositionelle <code>ComponentType</code>-Definition verweisen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erweitert die normative Modellierung atomarer Softwarekomponenten auf Anwendungssoftware (<code>ApplicationSoftwareComponentType</code>), Steuergeräte-Abstraktion (<code>EcuAbstractionComponentType</code>) und komplexe Treiber (<code>ComplexDeviceDriverComponentType</code>), wodurch diese Typen vollumfänglich als atomare Komponenten über Prototypen in Software-Kompositionen eingebunden und durch die RTE vermittelt werden können. Die Multiplizität von <code>1..*</code> erzwingt weiterhin das Vorhandensein mindestens eines Prototyps in jeder Komposition.</p>"}, {"id": "FIG-1d1a6a148eb62e54", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Klassifikation der AUTOSAR-Software-Komponenten im Kontext der Software-Component Template und der Runtime Environment (RTE). Das Diagramm stellt die vollständige Typisierungshierarchie der atomaren und kompositionellen Komponenten dar, einschließlich NVRAM-Block- und Service-Komponenten, sowie deren Instanziierung als Prototypen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>ComponentType</code>: Abstrakte Basisklasse mit Stereotyp <code>«atpType»</code>, spezialisiert <code>ARElement</code>.\n</li><li><code>AtomicSoftwareComponentType</code>: Abstrakte Spezialisierung von <code>ComponentType</code>.\n<ul class=\"fig-list\"><li><code>NvBlockSwComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code> für nichtflüchtige Speicherblöcke.\n</li><li><code>ApplicationSoftwareComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>SensorActuatorSoftwareComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ServiceComponentType</code>: Spezialisierung von <code>AtomicSoftwareComponentType</code> mit dem Stereotyp <code>«atpType»</code>.\n</li><li><code>EcuAbstractionComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ComplexDeviceDriverComponentType</code>: Konkrete Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li></ul>\n</li><li><code>CalprmComponentType</code>: Spezialisierung von <code>ComponentType</code> mit Stereotyp <code>«atpType»</code>.\n</li><li><code>CompositionType</code>: Spezialisierung von <code>ComponentType</code> mit Stereotyp <code>«atpType»</code>.\n</li><li><code>ComponentPrototype</code>: Entität mit Stereotyp <code>«atpPrototype»</code>, spezialisiert <code>Identifiable</code>.\n</li><li>Assoziationen und Kompositionen:\n<ul class=\"fig-list\"><li><code>ComponentPrototype</code> referenziert über die gerichtete Assoziation <code>«isOfType»</code> genau einen <code>ComponentType</code> (Rolle <code>+type</code>, Multiplizität <code>1</code>, Quellmultiplizität <code>*</code>).\n</li><li><code>CompositionType</code> aggregiert per Komposition null bis beliebig viele <code>ComponentPrototype</code>-Elemente (Rolle <code>+component</code>, Multiplizität <code>0..*</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Verhaltensabläufe. Die Instanziierungslogik ist deklarativ: Ein <code>CompositionType</code> aggregiert zur Entwurfszeit <code>ComponentPrototype</code>-Elemente, die jeweils typisiert über <code>«isOfType»</code> auf eine konkrete oder kompositionelle <code>ComponentType</code>-Definition verweisen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant ist die Lockerung der Kardinalität von <code>+component</code> auf <code>0..*</code>, womit leere Kompositionen formal zulässig werden (z. B. als Entwurfsmuster oder Platzhalter in frühen Architekturphasen). Die Aufnahme von <code>NvBlockSwComponentType</code> integriert NVRAM-relevante Softwarekomponenten direkt in das atomare Typensystem der RTE. Der Stereotyp <code>«atpType»</code> an <code>ServiceComponentType</code> vereinheitlicht die formale Typ-Klassifikation im Metamodell.</p>"}], "trans": [{"from": "FIG-e32cf82a3754aca0", "to": "FIG-3332cf3134fcc3ef", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzufügung der Klassen <code>ApplicationSoftwareComponentType</code>, <code>EcuAbstractionComponentType</code> und <code>ComplexDeviceDriverComponentType</code> als Spezialisierungen von <code>AtomicSoftwareComponentType</code>.\n</li><li>Hinzufügung des Diagrammrahmens <code>cd Components</code>.\n</li><li>Redaktionelle Korrektur des Tippfehlers in <code>ServiceComponentType</code> (dargestellt als <code>Serv iceComponentType</code>).\n</li></ul>"}, {"from": "FIG-3332cf3134fcc3ef", "to": "FIG-1d1a6a148eb62e54", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Änderung der Multiplizität der Komposition von <code>CompositionType</code> zu <code>ComponentPrototype</code> (<code>+component</code>) von <code>1..*</code> auf <code>0..*</code>.\n</li><li>Hinzufügung der Klasse <code>NvBlockSwComponentType</code> als Spezialisierung von <code>AtomicSoftwareComponentType</code>.\n</li><li>Hinzufügung des Stereotyps <code>«atpType»</code> zu <code>ServiceComponentType</code>.\n</li><li>Entfernung des Diagrammrahmens <code>cd Components</code>.\n</li><li>Redaktionelle Korrektur der Leerzeichen im Klassennamen von <code>ComplexDev iceDriverComponentType</code> zu <code>ComplexDeviceDriverComponentType</code> sowie <code>Serv iceComponentType</code> zu <code>ServiceComponentType</code>.\n</li></ul>"}]};
